#include<bits/stdc++.h>
using namespace std;
#define int long long
const int N=5e5+5,V=1e13+1025;
int n,T,vg,vw,vc,dp[N];//dp[i]表示 在他的掉落的时刻 恰好从他这边出发 往后至多得分
struct drop{
    int x,time;
}a[N];
int cmp(drop x,drop y){
    return x.time<y.time;
}
tuple<int,int,int>b[N],c[N];
struct fenwick{
    int t[N];
    fenwick(){
        memset(t,0,sizeof(t));
    }
    int lowbit(int x){
        return x&-x;
    }
    void update(int pos,int x,int val){
        for(int i=pos;i<=n;i+=lowbit(i)){
            if(!val){
                t[i]=0;
            }
            else{
                t[i]=max(t[i],x);
            }
        }
    }
    int query(int x){
        int ret=0;
        for(int i=x;i>=1;i-=lowbit(i)){
            ret=max(ret,t[i]);
        }
        return ret;
    }
}tree;
void cdq(int l,int r){
    if(l==r){
        return;
    }
    int mid=(l+r)>>1;
    cdq(mid+1,r);//左半部分 被右半部分更新
    for(int i=mid+1;i<=r;i++){
        b[i]={a[i].x,dp[i],a[i].time};
    }
    sort(b+mid+1,b+r+1);
    for(int i=l;i<=mid;i++){
        c[i]={a[i].x,i,a[i].time};
    }
    sort(c+l,c+mid+1);
    //现在右边的x在变大 左边的x也是 我们先考虑a[i].x>=a[j].x的部分 这是一个前缀
    int now=mid+1;
    vector<int>vec;
    for(int i=l;i<=r;i++){
        vec.push_back(-a[i].time-a[i].x);
    }
    sort(vec.begin(),vec.end());
    map<int,int>mp;
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
    }
    for(int i=l;i<=mid;i++){
        while(now<=r&&get<0>(b[now])<=get<0>(c[i])){
            tree.update(mp[-get<0>(b[now])-get<2>(b[now])],get<1>(b[now]),1),now++;
        }
        dp[get<1>(c[i])]=max(dp[get<1>(c[i])],tree.query(mp[-get<0>(c[i])-get<2>(c[i])])+1);
    }
    //这边xj>=xi的话 对于一个i 是一个后缀 之后随着i变小 会加入 
    for(int i=mid+1;i<now;i++){
        tree.update(mp[-get<0>(b[i])-get<2>(b[i])],get<1>(b[now]),0);
    }
    now=r,mp.clear(),vec.clear();
    for(int i=l;i<=r;i++){
        vec.push_back(a[i].x-a[i].time);
    }
    sort(vec.begin(),vec.end());
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
    }
    for(int i=mid;i>=l;i--){
        while(now>=mid+1&&get<0>(b[now])>=get<0>(c[i])){
            tree.update(mp[get<0>(b[now])-get<2>(b[now])],get<1>(b[now]),1),now--;
        }
        dp[get<1>(c[i])]=max(dp[get<1>(c[i])],tree.query(mp[get<0>(c[i])-get<2>(c[i])])+1);
    }
    for(int i=now+1;i<=r;i++){
        tree.update(mp[get<0>(b[i])-get<2>(b[i])],get<1>(b[i]),0);
    }
    cdq(l,mid);
}
struct segtree{
    int root,node;
    segtree(){
        root=node=0;
    }
    struct node{
        int l,r,max,val;
        node(){
            l=r=max=val=0;
        }
    }t[N*10];
    void addtag(int &u,int x){
        if(!u){
            u=++node;
        }
        t[u].max=max(t[u].max,x),t[u].val=max(x,t[u].val);
    }
    void pushdown(int u){
        addtag(t[u].l,t[u].max),addtag(t[u].r,t[u].max),t[u].max=0;
    }
    void update(int &u,int l,int r,int x,int L,int R){
        if(!u){
            u=++node;
        }
        if(L>=l&&R<=r){
            addtag(u,x);
            return;
        }
        pushdown(u);
        int mid=(L+R)>>1;
        if(l<=mid){
            update(t[u].l,l,r,x,L,mid);
        }
        if(r>mid){
            update(t[u].r,l,r,x,mid+1,R);
        }
    }
    int query(int u,int x,int l,int r){
        if(l==r){
            return t[u].val;
        }
        pushdown(u);
        int mid=(l+r)>>1;
        if(x<=mid){
            return query(t[u].l,x,l,mid);
        }
        return query(t[u].r,x,mid+1,r);
    }
}segtree;
vector<int>vec;
map<int,int>mp;
pair<int,int>q[N];
signed main(){
    ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
    cin>>n>>T>>vg>>vw>>vc;
    for(int i=1;i<=n;i++){
        cin>>a[i].x>>a[i].time;
        a[i].x=(a[i].x*vg+vw*a[i].time),dp[i]=1,a[i].time*=vc,vec.push_back(a[i].x-a[i].time),vec.push_back(a[i].x+a[i].time);
    }
    sort(a+1,a+n+1,cmp),cdq(1,n);
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
    }
    for(int i=1;i<=T;i++){
        cin>>q[i].first,q[i].first*=vg,vec.push_back(q[i].first),q[i].second=i;
    }
    sort(vec.begin(),vec.end());
    for(int i=0;i<vec.size();i++){
        mp[vec[i]]=i+1;
