        for(int i=1;i<=n;i++){
            rmq[i][0]=1e8+1025;
            if(i%2==target){
                rmq[i][0]=a[i],id[i][0]=i;
            }
        }
        for(int i=1;i<20;i++){
            for(int j=1;j+(1<<i)-1<=n;j++){
                rmq[j][i]=min(rmq[j][i-1],rmq[j+(1<<(i-1))][i-1]);
                if(rmq[j][i-1]==rmq[j][i]){
                    id[j][i]=id[j][i-1];
                }
                else{
                    id[j][i]=id[j+(1<<(i-1))][i-1];
                }
            }
        }
    }
    int query(int l,int r){
        int k=__lg(r-l+1);
        if(rmq[l][k]<=rmq[r-(1<<k)+1][k]){
            return id[l][k];
        }
        return id[r-(1<<k)+1][k];
    }
