const int N=2e3+5,mod=924844033;
int n,m,dp[N][N][3],f[N],g[N],fac[N]={1},newf[N];
void update(int r,int last,int num){
    for(int i=0;i<=num;i++){
        g[i]=(dp[last][i][0]+dp[last][i][1]+dp[last][i][2]);
    }
    for(int i=0;i<=n;i++){
        newf[i]=0;
    }
    for(int i=num;i>=0;i--){
        for(int j=n;j>=0;j--){
            if(i+j<=n){
                newf[i+j]=(newf[i+j]+g[i]*f[j])%mod;    
            }
        }
    }
    for(int i=0;i<=n;i++){
        f[i]=newf[i];
    }
}
signed main(){
    cin>>n>>m,f[0]=1;
    for(int i=1;i<=n;i++){
        fac[i]=fac[i-1]*i%mod;
    }
    for(int i=0;i<min(n,2*m);i++){
        for(int j=i;j<n;j+=2*m){
            for(int k=0;k<=n;k++){
                dp[j][k][0]=dp[j][k][1]=dp[j][k][2]=0;
            }
        }
        dp[i][0][2]=1;
        if(i-m>=0){
            dp[i][1][0]=1;    
        }            
        if(i+m<n){
            dp[i][1][1]=1;
        }
        int last=i,num=1;
        for(int j=i;j+2*m<n;j+=2*m){
            num++,last=j+2*m;
            for(int k=0;k<=n;k++){
                dp[j+2*m][k][2]=(dp[j+2*m][k][2]+dp[j][k][0]+dp[j][k][1]+dp[j][k][2])%mod;
