                    dp[j+2*m][k+1][1]=(dp[2*m+j][k+1][1]+dp[j][k][0]+dp[j][k][1]+dp[j][k][2])%mod;
                }
                dp[j+2*m][k+1][0]=(dp[2*m+j][k+1][0]+dp[j][k][0]+dp[j][k][2])%mod;    
            }
        }
        update(i,last,num);
    }
    int ans=1;
    for(int i=2;i<=n;i++){
        ans=ans*i%mod;
    }
    for(int i=1;i<=n;i++){
        f[i]=f[i]*fac[n-i]%mod;
        if(i%2==0){
            ans=(ans+f[i])%mod;
        }
        else{
            ans=(ans-f[i])%mod;
        }
    }
    cout<<(ans%mod+mod)%mod;
}

