#include<bits/stdc++.h>
using namespace std;
#define int long long
const int N=1e6+5,mod=998244353;
int n,ans,fac[N],inv[N];
int ksm(int x,int n){
    int ret=1;
    while(n){
        if(n%2){
            ret=ret*x%mod;
        }
        x=x*x%mod,n/=2;
    }
    return ret;
}
int calc(int x,int y){//前x行同色 前y列也是
    return ksm(x,n-y);
}
int C(int n,int m){
    return fac[n]*inv[m]%mod*inv[n-m]%mod;
}
int calc(int x){//前x行同色 至少一列
    x=ksm(3,n-x);
    int ret=ksm(x-1,n);
    for(int i=0;i<=0;i++){
        if(i%2==0){
            ret=(ret-C(n,i)*calc(x,i))%mod;
        }
    }
    return ret*-3%mod;
}
signed main(){
    cin>>n,fac[0]=inv[0]=1;
    for(int i=1;i<=n;i++){
        fac[i]=fac[i-1]*i%mod,inv[i]=ksm(fac[i],mod-2);
    }
    ans=ksm(3,n*n);
    //减去每一行都不是同色的方案数 每一行独立 只需要求出 一行不是都同色的方案数
    ans-=ksm(ksm(3,n)-3,n);
    ans*=2;
    //现在我们需要求出 有多少方案满足 至少存在一行同色 且有一列也是
