int lca(int u,int v){
    while(u!=v){
        if(depth[u]<depth[v]){
            v=f[v];
        }
        else{
            u=f[u];
        }
    }
    return u;
}
void dfs(int u,int last){
    depth[u]=depth[last]+1,f[u]=last;
    for(int v:g[u]){
